import{_ as n,o as s,c as a,j as e}from"./chunks/framework.44aEvdQQ.js";const u=JSON.parse('{"title":"Systems Thinking & Pattern Matching","description":"","frontmatter":{"title":"Systems Thinking & Pattern Matching","order":9,"subtitle":"Recognizing archetypes, developing instinct"},"headers":[],"relativePath":"about/chapters/09-systems-thinking-pattern-matching.md","filePath":"about/chapters/09-systems-thinking-pattern-matching.md"}'),i={name:"about/chapters/09-systems-thinking-pattern-matching.md"};function r(o,t,l,c,h,p){return s(),a("div",null,[...t[0]||(t[0]=[e("p",null,[e("em",null,"Recognizing archetypes, developing instinct")],-1),e("p",null,"Senge's systems thinking applied to daily professional work. Most situations are 5-6 recurring patterns. Ability to recognize which archetype you're in, predict consequences, short-circuit for best fit. Kahneman's System 1 vs System 2: Goal is to develop System 1 pattern matching through experience so you're not deep-diving constantly. This is mastery. Why AI can follow rules but can't improvise when patterns break. Human judgment developed through safe failure is irreplaceable. Small firms are messy because of the noise to signal ratio. There's too much noise to concentrate, and yet our best work happens when we can focus. Insisting on your business being a learning company is the only way to rationalize the noise, to make sense of signals, and to learn from (inevitable) mistakes.",-1),e("blockquote",null,[e("p",null,'"The art of progress is to preserve order amid change, and to preserve change amid order."'),e("ul",null,[e("li",null,"Alfred North Whitehead).")])],-1)])])}const g=n(i,[["render",r]]);export{u as __pageData,g as default};
